def collapse_whitespace(s):
    result = []
    prev_space = False
    for ch in s:
        if ch in (' ', '\t', '\n', '\r', '\v', '\f'):
            if not prev_space:
                result.append(' ')
                prev_space = True
        else:
            result.append(ch)
            prev_space = False
    # Strip leading and trailing spaces
